<?php
namespace App\Filament\Admin\Resources\Pembayarans\Pages;
use App\Filament\Admin\Resources\Pembayarans\PembayaranResource; use App\Models\Pembayaran; use App\Models\PembelianObat; use App\Notifications\PembayaranDibuatUntukSupplier; use Filament\Resources\Pages\EditRecord; use Illuminate\Validation\ValidationException;
class EditPembayaran extends EditRecord { protected static string $resource=PembayaranResource::class;
 protected function mutateFormDataBeforeSave(array $data):array { $po=PembelianObat::findOrFail($data['id_pembelian_obat']); if($po->status==='dibatalkan') throw ValidationException::withMessages(['id_pembelian_obat'=>'PO yang dibatalkan tidak dapat menerima pembayaran.']); $other=(int)$po->pembayaran()->where('id','!=',$this->record->id)->whereIn('status',['menunggu_supplier','disetujui_supplier'])->sum('total_bayar'); $sisa=max(0,$po->total_pesanan-$other); if((int)$data['total_bayar']>$sisa) throw ValidationException::withMessages(['total_bayar'=>'Pembayaran melebihi sisa tagihan yang tersedia. Maksimal Rp '.number_format($sisa,0,',','.').'.']); $data['status']='menunggu_supplier'; $data['disetujui_supplier_at']=null; $data['disetujui_supplier_oleh']=null; $data['ditolak_supplier_at']=null; $data['catatan_supplier']=null; return $data; }
 protected function afterSave():void { $supplierUser=$this->record->pembelian_obat?->supplier?->pengguna; if($supplierUser) $supplierUser->notify(new PembayaranDibuatUntukSupplier($this->record)); }
}
